def packet (N : ℕ) [NeZero N] (one : Bool) (S : Finset ℕ) (w : ℕ → ℂ) (ind : ℕ → ℤ)
    (ψ : ℝ → ℂ) (u : Gamma0OrbitSpace N) : ℂ :=
  ∑ b ∈ S,star (w b)*originalPoincare N one (ind b) (scaledSeed (ind b) ψ) u

def baseTerm (one neg : Bool) (K : ℝ) (S : Finset ℕ) (a : ℕ→ℂ) (i : Idx) : ℝ :=
  if ¬exceptional N i ∧ height N i≤K then
    ‖discreteRow N one neg S a i‖^2/Real.cosh (Real.pi*height N i) else 0

def vector (q : ℕ) [NeZero q] (S : Finset ℕ) (w : ℕ → ℂ) (f : ℕ → ℤ)
    (pos : ∀ n ∈ S, f n ≠ 0) (ψ : HeightSeed) : QuotientL2 q :=
  (packet_L2 q false S w f pos ψ.toFun ψ.continuous ψ.compact ψ.positive).toLp (packet q false S w f ψ.toFun)

def discrete (q : ℕ) [NeZero q] (S : Finset ℕ) (w : ℕ → ℂ) (f : ℕ → ℤ)
    (ψ : HeightSeed) (i : actualCuspBasisIndex q (NeZero.pos q)) : ℂ :=
  orderProbe 1 ψ.toFun (basisOrder q (NeZero.pos q) i)*markedRow S w f (basisR q (NeZero.pos q) i 1)

def continuousCoord (q : ℕ) [NeZero q] (S : Finset ℕ) (w : ℕ → ℂ) (f : ℕ → ℤ)
    (ψ : HeightSeed) (t : ℝ) (a : Parameters q) : ℂ :=
  radialProbe 1 ψ.toFun t*markedRow S w f (fun n => nativeR a false n t)

theorem compact_spectrum (q : ℕ) [NeZero q] (S T : Finset ℕ) (u v : ℕ→ℂ) (f g : ℕ→ℤ)
    (su : ∀ n ∈ S, f n ≠ 0) (tv : ∀ n ∈ T, g n ≠ 0) (ψ φ : HeightSeed) :
    let F := fun i => discrete q S u f ψ i * star (discrete q T v g φ i)
    let E := fun t => nativeProduct q (continuousCoord q T v g φ t) (continuousCoord q S u f ψ t)
    Summable F ∧ Integrable E ∧ inner ℂ (vector q S u f su ψ) (vector q T v g tv φ) =
      (∑' i, F i)+(∫ t : ℝ, E t)

def atom (q m : ℕ+) (ψ : HeightSeed) (i : actualCuspBasisIndex q.val (NeZero.pos q.val)) :=
  orderProbe 1 ψ.toFun (basisOrder q.val (NeZero.pos q.val) i)*
    basisR q.val (NeZero.pos q.val) i (1 : SL(2,ℤ)) (m.val:ℤ)

def eisenstein (q m n : ℕ+) (ψ φ : HeightSeed) (t : ℝ) :=
  nativeProduct q.val (fun a => radialProbe 1 φ.toFun t*ImbalancedChen.Part3.ActualContinuousClassFourier20261110.nativeR a false (n.val:ℤ) t)
    (fun a => radialProbe 1 ψ.toFun t*ImbalancedChen.Part3.ActualContinuousClassFourier20261110.nativeR a false (m.val:ℤ) t)

def actualCuspHilbertBasis (N : ℕ) [NeZero N] (hN : 0 < N) :
    HilbertBasis (actualCuspBasisIndex N hN) ℂ (ActualFullCuspL2 N hN) :=
  HilbertBasis.mk (actualCuspEigenvector_orthonormal N hN) (actualCuspEigenvector_dense_span N hN)

def actualCuspNativeEigenvalue (N : ℕ) [NeZero N] (hN : 0 < N)
    (i : actualCuspBasisIndex N hN) : ℝ :=
  variationalMaassEigenvalue (actualCuspResolventEigenvalue N hN i)
